+// top-picks drag & drop (pinning + reordering) — shared by the color and
+// font pickers. Strips opt in via `.top-picks-dnd` + `.top-picks-dnd__pick`.
+// -----------------------------------------------------------------------------
+
+.excalidraw {
+  .top-picks-dnd {
+    // anchor for the animated drop-target outline
+    position: relative;
+  }
+
+  .top-picks-dnd__pick {
+    // the strip is tiny and never scrolls — allow touch-dragging picks
+    touch-action: none;
+  }
+
+  .top-picks-dnd.is-dnd-active {
+    .top-picks-dnd__pick {
+      // no hover/tooltips while a drag is in flight; hit-testing is
+      // coordinate-based so this doesn't affect dropping
+      pointer-events: none;
+      transition: transform 0.14s ease, opacity 0.14s ease,
+        box-shadow 0.14s ease;
+    }
+  }
+
+  .top-picks-dnd__outline {
+    position: absolute;
+    top: -5px;
+    left: -5px;
+    width: calc(100% + 10px);
+    height: calc(100% + 10px);
+    pointer-events: none;
+    overflow: visible;
+
+    rect {
+      x: 0.5px;
+      y: 0.5px;
+      rx: 6px;
+      width: calc(100% - 1px);
+      height: calc(100% - 1px);
+      fill: none;
+      stroke: var(--color-primary);
+      stroke-width: 1;
+      stroke-dasharray: 4 4;
+      animation: excalidraw-top-picks-dnd-march 0.8s linear infinite;
+
+      @media (prefers-reduced-motion: reduce) {
+        animation: none;
+      }
+    }
+  }
+
+  @keyframes excalidraw-top-picks-dnd-march {
+    to {
+      // one full dash+gap period per cycle → seamless loop
+      stroke-dashoffset: -8;
+    }
+  }
+
+  // the pick being reordered — its ghost is following the pointer
+  .top-picks-dnd__pick.is-dnd-source {
+    opacity: 0.3;
+  }
+
+  // this value is already pinned — drop not allowed
+  .top-picks-dnd__pick.is-dnd-duplicate {
+    animation: excalidraw-top-picks-dnd-duplicate 0.45s ease-in-out infinite
+      alternate;
+  }
+
+  @keyframes excalidraw-top-picks-dnd-duplicate {
+    from {
+      box-shadow: 0 0 0 2px var(--color-danger, #e03131);
+      transform: scale(1);
+    }
+    to {
+      box-shadow: 0 0 0 3px var(--color-danger, #e03131);
+      transform: scale(1.12);
+    }
+  }
+
+  .top-picks-dnd__tip {
+    padding: 0 0.5rem;
+    font-size: 0.6875rem;
+    line-height: 1.4;
+    text-align: left;
+    color: var(--color-gray-60);
+  }
+
+  // plain-text link
+  .top-picks-dnd__tip-reset {
+    padding: 0;
+    margin: 0;
+    border: 0;
+    background: none;
+    font: inherit;
+    color: var(--color-primary);
+    cursor: pointer;
+
+    &:hover {
+      text-decoration: underline;
+    }
+  }
+
+  .top-picks-dnd__context-menu {
+    background: var(--popup-bg-color);
+    border-radius: var(--border-radius-lg);
+    box-shadow: var(--shadow-island);
+    padding: 0.25rem;
+  }
+
+  .top-picks-dnd__context-menu-item {
+    font-size: 0.75rem;
+    padding: 0.375rem 0.625rem;
+    border-radius: var(--border-radius-md);
+    color: var(--text-primary-color);
+    cursor: pointer;
+    outline: none;
+    user-select: none;
+
+    // :hover as well — radix only sets data-highlighted once the item gets
+    // focus via pointermove, which leaves dead frames (e.g. menu opening
+    // under a stationary cursor)
+    &[data-highlighted],
+    &:not([data-disabled]):hover {
+      background: var(--button-hover-bg);
+    }
+
+    &[data-disabled] {
+      opacity: 0.5;
+      pointer-events: none;
+    }
+  }
+}
+
+// drag & drop ghost — appended to document.body (outside the .excalidraw
+// scope) so it can follow the pointer without overflow clipping
+.excalidraw-top-picks-dnd-ghost {
+  position: fixed;
+  top: 0;
+  left: 0;
+  z-index: 10000;
+  pointer-events: none;
+  will-change: transform;
+  // NOTE transform is deliberately not transitioned here (tracks the pointer
+  // every frame); --dropping adds it for the fly-to-target animation
+  transition: width 0.15s ease, height 0.15s ease;
+
+  // content may set `--top-picks-dnd-ghost-ring` (a hairline box-shadow)
+  // to keep under the drop shadows below
+  &__content {
+    width: 100%;
+    height: 100%;
+    box-sizing: border-box;
+    box-shadow: var(--top-picks-dnd-ghost-ring, 0 0 transparent);
+    transition: transform 0.15s ease, opacity 0.15s ease, box-shadow 0.15s ease;
+  }
+
+  &--lifted &__content {
+    transform: scale(1.2);
+    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.25),
+      var(--top-picks-dnd-ghost-ring, 0 0 transparent);
+  }
+
+  &--over &__content {
+    transform: scale(1.05);
+    box-shadow: 0 3px 8px rgba(0, 0, 0, 0.2),
+      var(--top-picks-dnd-ghost-ring, 0 0 transparent);
+  }
+
+  &--blocked &__content {
+    opacity: 0.4;
+    transform: scale(0.85);
+  }
+
+  &--dropping {
+    transition: transform 0.18s cubic-bezier(0.2, 0.8, 0.3, 1), width 0.18s ease,
+      height 0.18s ease;
+  }
+
+  &--dropping &__content {
+    transform: scale(1);
+    box-shadow: var(--top-picks-dnd-ghost-ring, 0 0 transparent);
+  }
+
+  &--fade &__content {
+    opacity: 0;
+  }
+}
+
+body.excalidraw-top-picks-dnd-active {
+  user-select: none !important;
+  -webkit-user-select: none !important;
+
+  &,
+  * {
+    cursor: grabbing !important;
+  }
+}

